procedure BrewPartyBooking {
  about "Book private parties and schedule them on Patio"
  policy BrewPolicy
  sheet Parties "Parties" { host: Text, phone: Phone, party_at: DateTime, guests: Number, status: Text }
  calendar Patio "Patio"
  trigger when new row r in Parties

  if r.guests > 30 {
    notify owner "Private party booking for {r.host} with {r.guests} guests is over 30. Please cancel."
    stop "party size exceeds limit"
  }
  append Patio { title: "{r.host}", start: r.party_at, duration: 3 hours, description: "private party for {r.host} with {r.guests} guests" }
  let m = draft sms to r.host: "Hi {r.host}, your private party at {r.party_at} has been booked. Please confirm."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
  update r set status = "confirmed"
}
