procedure CampgroundCheckIns {
  about "Send check-in emails for reserved campers"
  policy CampgroundPolicy
  sheet Sites "Sites" { camper: Text, email: Email, site: Text, arrival: Date, nights: Number, status: Text, plate: Text private }
  trigger every morning at 10:00

  let all = fetch Sites
  let reserved = filter all where status == "reserved" and arrival == today() + 1
  let n = summarize count of reserved
  append Outreach { day: today(), campaign: "checkin", targeted: n }
