procedure CampgroundRefunds {
  about "Handle cancellation requests within limits"
  policy CampgroundPolicy
  sheet Cancellations "Cancellations" { booking: Text, camper: Text, deposit: Money, arrival: Date }
  trigger when new row r in Cancellations

  if days_between(arrival, today()) < 5 {
    notify owner "Cancellation request for {r.camper} is less than 5 days away."
    stop "cancellation too soon"
  }
  if r.deposit > $150.00 {
    notify owner "Deposit for {r.camper} is {r.deposit}, over $150. Please review."
    stop "deposit too high"
  }
  if r.deposit <= $50.00 {
    refund r.deposit for r.booking reason "cancellation request", ask owner first timeout 6 hours else skip
  } else {
    refund r.deposit for r.booking reason "cancellation request", ask owner first timeout 6 hours else skip
  }
  update r set status = "refunded"
  let m = draft sms to r.camper: "Hi {r.camper}, your cancellation of {r.booking} has been processed."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
}
```

