procedure CampgroundBookings {
  about "Count reserved sites and total nights"
  policy CampgroundPolicy
  sheet Sites "Sites" { camper: Text, email: Email, site: Text, arrival: Date, nights: Number, status: Text, plate: Text private }
  trigger every day at 6:00

  let all = fetch Sites
  let reserved = filter all where status == "reserved"
  let upcoming = filter reserved where arrival >= today()
  let count = summarize count of upcoming
  let total_nights = summarize sum(nights) of upcoming
  notify owner "There are {count} reserved sites arriving in the next 30 days, totaling {total_nights} nights."
}

