  sheet Sites "Sites" { camper: Text, email: Email, site: Text, arrival: Date, nights: Number, status: Text, plate: Text private }
  trigger every day at 10:30

  let all = fetch Sites
  let upcoming = filter all where arrival == today() + 1 and status == "available"
