procedure MassageCardRefunds {
  about "Handle gift card refunds within limits"
  policy MassagePolicy
  sheet GiftRefunds "GiftRefunds" { card_id: Text, buyer: Text, amount: Money, bought_on: Date }
  trigger when new row r in GiftRefunds

  if days_between(r.bought_on, today()) > 90 {
    notify owner "Gift card refund request {r.card_id} is older than 90 days."
    stop "outside refund window"
  }
  if r.amount <= $30.00 {
    refund r.amount for r.card_id reason "gift card refund", ask owner first timeout 6 hours else skip
  }
  if r.amount <= $100.00 {
    refund r.amount for r.card_id reason "gift card refund", ask owner first timeout 6 hours else skip
  }
  if r.amount > $100.00 {
    refund r.amount for r.card_id reason "personal refund", ask owner first timeout 6 hours else skip
  }
}
