procedure StudioWeeklyBookings {
  about "Find weekly bookings and biggest session"
  policy StudioPolicy
  sheet Sessions "Sessions" { artist: Text, email: Email, session_at: DateTime, hours: Number, deposit: Money, status: Text, contract_terms: Text private }
  trigger every Sunday at 22:00

  let all = fetch Sessions
  let booked_this_week = filter all where status == "booked" and date_of(session_at) >= today() - 7 days
  let total_hours_booked = summarize sum(hours) of booked_this_week
  let biggest_session = filter booked_this_week where hours == max(hours)
  let m = draft sms to owner: "Total hours booked this coming week: {total_hours_booked}. Biggest session: {biggest_session.hours} hours."
  let ok = request approval of m from owner timeout 2 hours else skip
  send ok
}

