procedure StudioRefunds {
  about "Handle studio session cancellations within limits"
  policy StudioPolicy
  sheet StudioCancels "StudioCancels" { session_ref: Text, artist: Text, email: Email, deposit: Money, session_at: DateTime }
  trigger when new row r in StudioCancels

  if days_between(r.session_at, today()) > 48 {
    notify owner "Session cancellation {r.session_ref} is more than 48 hours old."
    stop "session too old"
  }
  if r.deposit > $200.00 {
    notify owner "Deposit for session {r.session_ref} is {r.deposit}. Please review."
    stop "deposit too high"
  }
  refund r.deposit for r.session_ref reason "studio session cancellation", ask owner first timeout 6 hours else stop "refund not approved"
  update r set status = "refunded"
  let m = draft sms to r.artist: "Hi {r.artist default 'there'}, your refund of {r.deposit} has been issued."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
}
```

