  policy TailorPolicy
  sheet Alterations "Alterations" { ticket: Text, customer: Text, phone: Phone, due: Date, price: Money, status: Text, measurements: Text private }
  trigger every morning at 10:30

  let all = fetch Alterations
  let ready = filter all where status == "ready" and measurements != ""
  for each r in ready up to 30 {
    let m = draft sms to r.phone: "Hi {r.customer default 'there'}, here are your measurements: {r.measurements}. Please check them."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
}
```

