procedure TailorRefunds {
  about "Handle refunds for botched alterations"
  policy TailorPolicy
  sheet TailorRefunds "TailorRefunds" { ticket: Text, customer: Text, price: Money }
  trigger when new row r in TailorRefunds

  refund r.price for r.ticket reason "botched alteration", ask owner first timeout 6 hours else skip
}
